// Packs the served vision photos into one script so the app also works opened from disk (file://).
// Chrome blocks fetch() of local files and canvas reads of local images, but it runs a local <script>,
// and images given as data: URLs keep the canvas readable for the pixel rules.
// Usage: node tools/vision-bundle.mjs   (rerun whenever the JPEGs or manifest.json in assets/vision-realistic/web/ change)
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'assets', 'vision-realistic', 'web');
const OUT = path.join(DIR, 'photos.js');
const MIME = { jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', webp: 'image/webp' };

const manifest = JSON.parse(fs.readFileSync(path.join(DIR, 'manifest.json'), 'utf8'));
if (manifest.version !== 1 || !Array.isArray(manifest.images)) throw new Error('manifest.json: expected version 1 with an images array');

const images = {};
for (const e of manifest.images) {
  const file = String(e.file || '');
  const mime = MIME[(file.split('.').pop() || '').toLowerCase()];
  if (!/^[A-Za-z0-9_-]+\.(png|jpe?g|webp)$/i.test(file) || !mime) throw new Error(`manifest.json: bad file name "${file}"`);
  images[file] = `data:${mime};base64,` + fs.readFileSync(path.join(DIR, file)).toString('base64');
}

const head = '// Generated by tools/vision-bundle.mjs from manifest.json and the photos in this folder. Do not edit; rerun the script.\n';
fs.writeFileSync(OUT, head + 'window.RYBEX_VISION_BUNDLE=' + JSON.stringify({ manifest, images }) + ';\n');
console.log(`${path.relative(process.cwd(), OUT)}: ${Object.keys(images).length} photos, ${(fs.statSync(OUT).size / 1e6).toFixed(1)} MB`);
